"""Database models for Day Trading & Intraday Intelligence module.

All monetary values in INR. All timestamps in Asia/Kolkata.
PAPER TRADING ONLY — no live broker integration.
"""

import uuid
from decimal import Decimal
from django.db import models
from django.utils import timezone


# ---------------------------------------------------------------------------
# Day Trade Plan
# ---------------------------------------------------------------------------
class DayTradePlan(models.Model):
    """Intraday trading plan generated by the scanner → entry pipeline."""

    DIRECTION_CHOICES = [("LONG", "Long"), ("SHORT", "Short")]
    STATUS_CHOICES = [
        ("PENDING", "Pending"),
        ("ACTIVE", "Active"),
        ("FILLED", "Filled"),
        ("EXITED", "Exited"),
        ("CANCELLED", "Cancelled"),
        ("EXPIRED", "Expired"),
    ]
    STRATEGY_CHOICES = [
        ("ORB", "Opening Range Breakout"),
        ("MOMENTUM", "Momentum"),
        ("VWAP_BOUNCE", "VWAP Bounce"),
        ("BREAKOUT", "Breakout"),
        ("BULL_FLAG", "Bull Flag"),
        ("MEAN_REVERT", "Mean Reversion"),
        ("CUSTOM", "Custom"),
    ]

    plan_id = models.CharField(max_length=64, primary_key=True, default=uuid.uuid4)
    symbol = models.CharField(max_length=30, db_index=True, help_text="e.g. RELIANCE.NS")
    exchange = models.CharField(max_length=10, default="NSE")
    strategy = models.CharField(max_length=20, choices=STRATEGY_CHOICES, default="ORB")
    direction = models.CharField(max_length=5, choices=DIRECTION_CHOICES, default="LONG")
    status = models.CharField(max_length=12, choices=STATUS_CHOICES, default="PENDING")

    # Entry parameters
    entry_price = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True)
    entry_trigger = models.CharField(max_length=255, blank=True, default="")
    entry_time = models.DateTimeField(null=True, blank=True)

    # Exit parameters
    stop_loss = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True)
    target_1 = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True)
    target_2 = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True)
    trailing_stop_pct = models.DecimalField(max_digits=5, decimal_places=2, null=True, blank=True)

    # Risk parameters
    quantity = models.IntegerField(default=0)
    risk_amount = models.DecimalField(max_digits=12, decimal_places=2, default=0)
    risk_reward_ratio = models.DecimalField(max_digits=5, decimal_places=2, default=0)
    position_value = models.DecimalField(max_digits=14, decimal_places=2, default=0)

    # Metadata
    scanner_score = models.FloatField(null=True, blank=True)
    rationale = models.TextField(blank=True, default="")
    indicators_snapshot = models.JSONField(default=dict, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ['-created_at']
        verbose_name = "Day Trade Plan"

    def __str__(self):
        return f"{self.symbol} {self.strategy} {self.direction} ({self.status})"


# ---------------------------------------------------------------------------
# Paper Broker Models
# ---------------------------------------------------------------------------
class PaperOrder(models.Model):
    """Simulated paper order — NEVER connected to a real broker."""

    SIDE_CHOICES = [("BUY", "Buy"), ("SELL", "Sell")]
    ORDER_TYPE_CHOICES = [
        ("MARKET", "Market"),
        ("LIMIT", "Limit"),
        ("SL", "Stop-Loss"),
        ("SL_LIMIT", "Stop-Loss Limit"),
    ]
    STATUS_CHOICES = [
        ("PENDING", "Pending"),
        ("OPEN", "Open"),
        ("FILLED", "Filled"),
        ("PARTIAL", "Partially Filled"),
        ("CANCELLED", "Cancelled"),
        ("REJECTED", "Rejected"),
    ]
    PRODUCT_CHOICES = [
        ("MIS", "Intraday (MIS)"),
        ("CNC", "Delivery (CNC)"),
    ]

    order_id = models.CharField(max_length=64, primary_key=True, default=uuid.uuid4)
    plan = models.ForeignKey(DayTradePlan, on_delete=models.SET_NULL, null=True, blank=True, related_name='orders')
    symbol = models.CharField(max_length=30, db_index=True)
    exchange = models.CharField(max_length=10, default="NSE")
    side = models.CharField(max_length=4, choices=SIDE_CHOICES)
    order_type = models.CharField(max_length=12, choices=ORDER_TYPE_CHOICES, default="MARKET")
    product = models.CharField(max_length=5, choices=PRODUCT_CHOICES, default="MIS")
    quantity = models.IntegerField()
    price = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True, help_text="Limit price in INR")
    trigger_price = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True, help_text="SL trigger")
    status = models.CharField(max_length=12, choices=STATUS_CHOICES, default="PENDING")
    filled_qty = models.IntegerField(default=0)
    avg_fill_price = models.DecimalField(max_digits=12, decimal_places=2, null=True, blank=True)
    rejection_reason = models.CharField(max_length=255, blank=True, default="")

    # Paper-only flag — ALWAYS True, server-side enforced
    is_paper = models.BooleanField(default=True, editable=False)

    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ['-created_at']
        verbose_name = "Paper Order"

    def save(self, *args, **kwargs):
        # SERVER-SIDE ENFORCEMENT: orders are ALWAYS paper
        self.is_paper = True
        super().save(*args, **kwargs)

    def __str__(self):
        return f"[PAPER] {self.side} {self.quantity} {self.symbol} @ {self.price or 'MKT'} ({self.status})"


class PaperFill(models.Model):
    """Simulated fill for a paper order."""

    fill_id = models.CharField(max_length=64, primary_key=True, default=uuid.uuid4)
    order = models.ForeignKey(PaperOrder, on_delete=models.CASCADE, related_name='fills')
    fill_price = models.DecimalField(max_digits=12, decimal_places=2)
    filled_qty = models.IntegerField()
    filled_at = models.DateTimeField(default=timezone.now)

    # Indian transaction costs
    brokerage = models.DecimalField(max_digits=10, decimal_places=2, default=0)
    stt = models.DecimalField(max_digits=10, decimal_places=2, default=0, help_text="Securities Transaction Tax")
    exchange_charges = models.DecimalField(max_digits=10, decimal_places=2, default=0)
    gst = models.DecimalField(max_digits=10, decimal_places=2, default=0)
    sebi_fee = models.DecimalField(max_digits=10, decimal_places=4, default=0)
    stamp_duty = models.DecimalField(max_digits=10, decimal_places=2, default=0)
    total_charges = models.DecimalField(max_digits=10, decimal_places=2, default=0)

    class Meta:
        ordering = ['-filled_at']

    def __str__(self):
        return f"Fill {self.filled_qty}@₹{self.fill_price} for {self.order.symbol}"


class PaperPosition(models.Model):
    """Aggregated simulated position from paper fills."""

    symbol = models.CharField(max_length=30, db_index=True)
    exchange = models.CharField(max_length=10, default="NSE")
    quantity = models.IntegerField(default=0)
    avg_entry_price = models.DecimalField(max_digits=12, decimal_places=2, default=0)
    current_price = models.DecimalField(max_digits=12, decimal_places=2, default=0)
    unrealized_pnl = models.DecimalField(max_digits=14, decimal_places=2, default=0)
    realized_pnl = models.DecimalField(max_digits=14, decimal_places=2, default=0)
    total_charges = models.DecimalField(max_digits=12, decimal_places=2, default=0)
    is_open = models.BooleanField(default=True, db_index=True)
    opened_at = models.DateTimeField(default=timezone.now)
    closed_at = models.DateTimeField(null=True, blank=True)

    # Paper-only flag — ALWAYS True
    is_paper = models.BooleanField(default=True, editable=False)

    class Meta:
        ordering = ['-opened_at']

    def save(self, *args, **kwargs):
        self.is_paper = True
        if self.quantity != 0 and self.avg_entry_price:
            self.unrealized_pnl = (self.current_price - self.avg_entry_price) * self.quantity
        super().save(*args, **kwargs)

    def __str__(self):
        tag = "OPEN" if self.is_open else "CLOSED"
        return f"[PAPER {tag}] {self.symbol} {self.quantity}@₹{self.avg_entry_price}"


# ---------------------------------------------------------------------------
# Paper Portfolio Account
# ---------------------------------------------------------------------------
class PaperAccount(models.Model):
    """Simulated brokerage account — paper capital only."""

    account_id = models.CharField(max_length=64, primary_key=True, default=uuid.uuid4)
    name = models.CharField(max_length=100, default="Default Paper Account")
    initial_capital = models.DecimalField(max_digits=14, decimal_places=2, default=1000000)
    available_cash = models.DecimalField(max_digits=14, decimal_places=2, default=1000000)
    used_margin = models.DecimalField(max_digits=14, decimal_places=2, default=0)
    realized_pnl = models.DecimalField(max_digits=14, decimal_places=2, default=0)
    total_charges = models.DecimalField(max_digits=12, decimal_places=2, default=0)
    daily_loss_limit = models.DecimalField(max_digits=12, decimal_places=2, default=20000, help_text="Max daily loss in INR")
    max_position_pct = models.DecimalField(max_digits=5, decimal_places=2, default=20, help_text="Max single position %")
    max_open_positions = models.IntegerField(default=5)
    is_paper = models.BooleanField(default=True, editable=False)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    def save(self, *args, **kwargs):
        self.is_paper = True
        super().save(*args, **kwargs)

    def __str__(self):
        return f"[PAPER] {self.name} — ₹{self.available_cash:,.2f} available"


# ---------------------------------------------------------------------------
# Scanner Results
# ---------------------------------------------------------------------------
class ScanResult(models.Model):
    """Stock screening / scanner hit."""

    SCAN_TYPE_CHOICES = [
        ("MOMENTUM", "Momentum"),
        ("VOLUME_SPIKE", "Volume Spike"),
        ("BREAKOUT", "Breakout"),
        ("ORB", "Opening Range Breakout"),
        ("BULL_FLAG", "Bull Flag"),
        ("VOLATILITY", "Volatility"),
        ("GAP_UP", "Gap Up"),
        ("GAP_DOWN", "Gap Down"),
    ]

    symbol = models.CharField(max_length=30, db_index=True)
    exchange = models.CharField(max_length=10, default="NSE")
    scan_type = models.CharField(max_length=20, choices=SCAN_TYPE_CHOICES)
    score = models.FloatField(default=0.0, help_text="Scanner composite score 0-100")
    price = models.DecimalField(max_digits=12, decimal_places=2, null=True)
    volume = models.BigIntegerField(null=True, blank=True)
    volume_ratio = models.FloatField(null=True, blank=True, help_text="Volume vs 20d avg")
    change_pct = models.FloatField(null=True, blank=True)
    rsi = models.FloatField(null=True, blank=True)
    atr = models.FloatField(null=True, blank=True)
    details = models.JSONField(default=dict, blank=True)
    scanned_at = models.DateTimeField(default=timezone.now, db_index=True)

    class Meta:
        ordering = ['-score', '-scanned_at']

    def __str__(self):
        return f"{self.symbol} [{self.scan_type}] score={self.score:.1f}"


# ---------------------------------------------------------------------------
# News & Sentiment
# ---------------------------------------------------------------------------
class NewsItem(models.Model):
    """Indian market news item with sentiment."""

    SENTIMENT_CHOICES = [
        ("POSITIVE", "Positive"),
        ("NEGATIVE", "Negative"),
        ("NEUTRAL", "Neutral"),
    ]
    SOURCE_CHOICES = [
        ("BSE", "BSE Announcements"),
        ("NSE", "NSE Announcements"),
        ("MONEYCONTROL", "Moneycontrol"),
        ("ET", "Economic Times"),
        ("YAHOO", "Yahoo Finance India"),
        ("REUTERS", "Reuters India"),
        ("RSS", "RSS Feed"),
        ("OTHER", "Other"),
    ]

    news_id = models.CharField(max_length=128, primary_key=True, default=uuid.uuid4)
    headline = models.CharField(max_length=500)
    summary = models.TextField(blank=True, default="")
    url = models.URLField(max_length=500, blank=True, default="")
    source = models.CharField(max_length=20, choices=SOURCE_CHOICES, default="OTHER")
    symbols = models.JSONField(default=list, blank=True, help_text="Related symbols")
