# ---------------------------------------------------------------------------
# Trade Journal
# ---------------------------------------------------------------------------
class TradeJournalEntry(models.Model):
    """Post-trade journal entry for learning and review."""

    DIRECTION_CHOICES = [("LONG", "Long"), ("SHORT", "Short")]
    OUTCOME_CHOICES = [("WIN", "Win"), ("LOSS", "Loss"), ("BREAKEVEN", "Breakeven")]

    journal_id = models.CharField(max_length=64, primary_key=True, default=uuid.uuid4)
    symbol = models.CharField(max_length=30, db_index=True)
    trade_date = models.DateField(db_index=True)
    strategy = models.CharField(max_length=30, blank=True, default="")
    direction = models.CharField(max_length=5, choices=DIRECTION_CHOICES, default="LONG")
    entry_price = models.DecimalField(max_digits=12, decimal_places=2)
    exit_price = models.DecimalField(max_digits=12, decimal_places=2)
    quantity = models.IntegerField(default=0)
    pnl_amount = models.DecimalField(max_digits=14, decimal_places=2, default=0)
    pnl_pct = models.FloatField(default=0.0)
    charges = models.DecimalField(max_digits=10, decimal_places=2, default=0)
    outcome = models.CharField(max_length=12, choices=OUTCOME_CHOICES, default="BREAKEVEN")
    notes = models.TextField(blank=True, default="")
    lessons = models.TextField(blank=True, default="")
    screenshots = models.JSONField(default=list, blank=True)
    plan = models.ForeignKey(DayTradePlan, on_delete=models.SET_NULL, null=True, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        ordering = ['-trade_date']

    def __str__(self):
        return f"{self.trade_date} {self.symbol} {self.outcome}: ₹{self.pnl_amount}"


# ---------------------------------------------------------------------------
# Intraday Candle Cache (for scanner / entry / time machine)
# ---------------------------------------------------------------------------
class IntradayCandle(models.Model):
    """Cached intraday OHLCV candle — 1m/5m/15m."""

    symbol = models.CharField(max_length=30, db_index=True)
    timeframe = models.CharField(max_length=5, default="5m", help_text="1m, 5m, 15m")
    timestamp = models.DateTimeField(db_index=True)
    open = models.DecimalField(max_digits=12, decimal_places=2)
    high = models.DecimalField(max_digits=12, decimal_places=2)
    low = models.DecimalField(max_digits=12, decimal_places=2)
    close = models.DecimalField(max_digits=12, decimal_places=2)
    volume = models.BigIntegerField(default=0)

    class Meta:
        ordering = ['timestamp']
        constraints = [
            models.UniqueConstraint(
                fields=['symbol', 'timeframe', 'timestamp'],
                name='unique_intraday_candle'
            )
        ]

    def __str__(self):
        return f"{self.symbol} {self.timeframe} {self.timestamp}: ₹{self.close}"
